 public void SelectCategory(int value){category=Mathf.Clamp(value,0,3);selected="";fingerprint="";Refresh(true);}
 public RiftInventoryItem Item(string id)=>items?.FirstOrDefault(i=>i.Id==id);
 public void Select(string id){selected=id??"";Refresh(false);}
 public bool MoveItem(string id,int slot){var item=Item(id);if(item!=null&&!item.Equipped&&layout.Move(id,slot,player.PlayerInfo.CharacterId)){fingerprint="";Refresh(true);return true;}return false;}
 public bool Equip(string id,bool offhand=false){var item=Item(id);if(item==null||item.IsConsumable||item.Equipped||(offhand&&!item.ShieldSet))return false;player.GetComponent<RiftJournalPlayer>()?.CmdWarriorWeapon(item.ShieldSet);return true;}
 public void ActSelected(){var item=Item(selected);if(item==null)return;if(item.IsConsumable){if(CanUse(item,out _))player.GetComponent<ROM.Horde.RiftVillagePlayer>()?.CmdDrinkPotion(item.Supply);}else if(!item.Equipped&&combat.CanChangeBuild)Equip(item.Id);}
 void Sort(){var ids=items.OrderBy(i=>i.Kind).ThenBy(i=>i.Name).Select(i=>i.Id).ToArray();layout.Items=new string[RiftBagLayout.Slots];Array.Copy(ids,layout.Items,Mathf.Min(ids.Length,layout.Items.Length));layout.Save(player.PlayerInfo.CharacterId);fingerprint="";Refresh(true);}
 void Update(){if(DragView==this&&Keyboard.current!=null&&Keyboard.current.escapeKey.wasPressedThisFrame){CancelDrag();RiftControls.EscapeConsumedFrame=Time.frameCount;return;}if(!RiftControls.TextEntryFocused&&!RiftControls.Rebinding){foreach(var item in items.Where(i=>i.IsConsumable))if(RiftControls.Pressed(item.Binding)&&CanUse(item,out _)){player.GetComponent<ROM.Horde.RiftVillagePlayer>()?.CmdDrinkPotion(item.Supply);RiftControls.InterfaceConsumedFrame=Time.frameCount;}}if(Time.unscaledTime<next)return;next=Time.unscaledTime+.15f;Refresh(false);}
 void OnDisable(){if(DragView==this)CancelDrag();}
 void JournalChanged(){fingerprint="";}
 void OnDestroy(){RiftJournalView.Changed-=JournalChanged;}
 void OnApplicationFocus(bool focus){if(!focus&&DragView==this)CancelDrag();}
 static void Clear(Transform root){for(int i=root.childCount-1;i>=0;i--)Destroy(root.GetChild(i).gameObject);}
 bool Visible(RiftInventoryItem item)=>item!=null&&!item.Equipped&&item.Count>0&&(category==0||category==1&&!item.IsConsumable||category==2&&item.IsConsumable);
 bool CanUse(RiftInventoryItem item,out string reason){var village=player.GetComponent<ROM.Horde.RiftVillagePlayer>();var actor=player.MyCharacter;double wait=village?Math.Max(0,village.PotionReadyAt-NetworkTime.time):0;reason=!player.isLocalPlayer||!NetworkServer.active?"Provisiones: cartera local; cliente remoto aún no disponible.":!actor||actor.Health.CurrentHealth<=0?"Necesitás estar vivo.":item.Count<=0?"Sin existencias. Visitá la boticaria.":actor.Health.CurrentHealth>=actor.Health.MaxHealth?"Tu vida está completa.":wait>0?"Recarga compartida: "+wait.ToString("0.0")+" s":"Clic derecho, botón o "+RiftControls.ActionLabel(item.Binding);return village&&player.isLocalPlayer&&NetworkServer.active&&actor&&actor.Health.CurrentHealth>0&&actor.Health.CurrentHealth<actor.Health.MaxHealth&&item.Count>0&&wait<=0;}
 void Refresh(bool force){if(!player||!player.MyCharacter||!stats)return;items=RiftInventoryItems.Read(player,combat);var actor=player.MyCharacter;nameText.text=actor.Health.CharacterName;stats.text="Warrior · Nivel "+combat.Level;statValues[0].text=actor.Health.CurrentHealth+" / "+actor.Health.MaxHealth;statValues[1].text="×"+(combat.PowerMultiplier*combat.WeaponMultiplier).ToString("0.##");statValues[2].text=(combat.CriticalChance*100).ToString("0.#")+"%";statValues[3].text=(combat.ExtraArmor*100).ToString("0.#")+"%";
  string visual=string.Join("|",actor.CharacterParent.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy).Select(r=>r.GetInstanceID().ToString()));if(actorGear!=visual||preview.SourceCharacter!=actor){actorGear=visual;preview.ShowLiveCharacter(actor);foreach(var pose in preview.PreviewSubject.GetComponentsInChildren<Animator>(true))pose.speed=0;preview.SetInspectionZoom(.8f);}
  string signature=category+"|"+string.Join("|",items.Select(i=>i.Id+":"+i.Count+":"+i.Equipped))+"|"+string.Join(",",layout.Items);if(force||signature!=fingerprint){fingerprint=signature;BuildGear();BuildGrid();BuildQuest();}
  for(int tab=0;tab<tabs.Length;tab++)RiftModernWidgets.Tab(tabs[tab],tab==category);foreach(var cell in GetComponentsInChildren<RiftInventoryCell>()){var edge=cell.GetComponent<Outline>();if(edge)edge.effectColor=!string.IsNullOrEmpty(selected)&&cell.ItemId==selected?Amber:new Color(.25f,.27f,.33f,.5f);}
  var item=Item(selected);selection.text=item==null?"":item.Name;action.gameObject.SetActive(category!=3&&item!=null&&!item.Equipped);if(item!=null){if(item.IsConsumable){action.GetComponentInChildren<Text>().text="USAR ["+RiftControls.ActionLabel(item.Binding)+"]";action.interactable=CanUse(item,out var reason);status.text=reason;}else{action.GetComponentInChildren<Text>().text=item.Equipped?"EQUIPADO":"EQUIPAR";action.interactable=!item.Equipped&&combat.CanChangeBuild;status.text=item.Equipped?"":combat.CanChangeBuild?"Clic derecho o Enter para equipar el conjunto.":"Volvé al refugio o salí de combate para cambiar equipo.";}}else status.text=category==3?"Los objetos de misión no se venden ni se transfieren.":"Arrastrá para ordenar; soltá equipo en la mano compatible.";
  coins.text=player.isLocalPlayer&&NetworkServer.active?"ORO DE EL RIFT   "+RiftExplorationProgress.Gold.ToString("N0"):"ORO · cartera remota no disponible";
