 void BuildGrid(){Clear(grid);grid.gameObject.SetActive(category!=3);int count=0;for(int slot=0;slot<RiftBagLayout.Slots;slot++){int index=slot;var item=Item(layout.Items[slot]);if(!Visible(item))item=null;else count++;var root=RiftModernWidgets.Panel(grid,"Inventory position "+slot,36+(slot%6)*146,(slot/6)*146,130,130);root.GetComponent<Image>().color=new Color(.008f,.01f,.018f,.65f);var cell=root.gameObject.AddComponent<RiftInventoryCell>();cell.View=this;cell.Position=index;cell.ItemId=item?.Id??"";cell.EquipmentTarget=false;
   root.GetComponent<Image>().raycastTarget=true;var button=root.gameObject.AddComponent<Button>();button.targetGraphic=root.GetComponent<Image>();RiftModernWidgets.Palette(button);string id=cell.ItemId;button.onClick.AddListener(()=>Select(id));var tip=root.gameObject.AddComponent<RiftTooltipTrigger>();
