 }
 void BuildGear(){Clear(gearRoot);var main=items.FirstOrDefault(i=>!i.IsConsumable&&i.Equipped&&i.Id!="starter:shield");var off=items.FirstOrDefault(i=>i.Id=="starter:shield"&&i.Equipped);GearSlot(main,false,780,28);GearSlot(off,true,780,230);}
 void GearSlot(RiftInventoryItem item,bool off,float x,float y){var root=RiftModernWidgets.Panel(gearRoot,off?"Off-hand equipment":"Main-hand equipment",x,y,132,166);root.GetComponent<Image>().color=new Color(.008f,.01f,.018f,.75f);root.GetComponent<Image>().raycastTarget=true;var button=root.gameObject.AddComponent<Button>();button.targetGraphic=root.GetComponent<Image>();RiftModernWidgets.Palette(button);button.onClick.AddListener(()=>{if(item!=null)Select(item.Id);else{SelectCategory(1);Select("starter:shield");}});var cell=root.gameObject.AddComponent<RiftInventoryCell>();cell.View=this;cell.ItemId=item?.Id??"";cell.EquipmentTarget=true;cell.Offhand=off;if(item?.Model)RiftItemArt.Place(root,item.Model,14,8,104);else RiftWidgets.Label(root,"DOS\nMANOS",8,28,116,65,18,RiftWidgets.Muted).alignment=TextAnchor.MiddleCenter;RiftWidgets.Label(root,off?"SECUNDARIA":"PRINCIPAL",0,134,132,24,13,RiftWidgets.Muted).alignment=TextAnchor.MiddleCenter;if(item!=null)RiftWidgets.Label(root,"ACTIVO",0,113,132,20,12,Amber).alignment=TextAnchor.MiddleCenter;var tip=root.gameObject.AddComponent<RiftTooltipTrigger>();tip.Title=item?.Name??"Mano secundaria ocupada";tip.Description=item?.Description??"El hacha usa ambas manos. Clic para seleccionar el escudo de tu equipo inicial; equiparlo cambia al conjunto espada y escudo.";}
 void BuildQuest(){Clear(questRoot);questRoot.gameObject.SetActive(category==3);if(category!=3)return;var state=RiftJournalView.Read();var catalog=RiftJournalCatalog.Load;var lines=new List<string>();if(state!=null&&catalog)foreach(var record in state.Quests.Where(q=>q.Status!=QuestStatus.TurnedIn)){var definition=catalog.Quest(record.Id);if(!definition)continue;for(int i=0;i<definition.Objectives.Length;i++){var objective=definition.Objectives[i];if(objective.Event!=RiftProgressEvent.Collect)continue;int value=record.Progress!=null&&i<record.Progress.Length?record.Progress[i]:0;lines.Add(definition.Title+" · "+objective.Label+"  "+value+" / "+objective.Required);}}
  var area=RiftWidgets.ScrollArea(questRoot,"Quest collection progress",0,0,932,110,Mathf.Max(110,lines.Count*35));RiftWidgets.Label(area,lines.Count==0?"Sin recolecciones activas. Aceptá una misión para ver su registro.":string.Join("\n",lines),12,0,896,Mathf.Max(110,lines.Count*35),20);RiftModernWidgets.Button(questRoot,"ABRIR DIARIO ["+RiftControls.ActionLabel("Journal")+"]",0,125,440,40,()=>hub.ShowGameplayPage(HubPage.Missions));empty.text="REGISTRO DE RECOLECCIÓN · progreso de misión, no objetos de bolsa";}
