public sealed class RiftInventoryCell:MonoBehaviour,IPointerClickHandler,IBeginDragHandler,IDragHandler,IEndDragHandler,IDropHandler,ISelectHandler,ISubmitHandler {
 public RiftInventoryPaperdoll View;public string ItemId;public int Position;public bool EquipmentTarget,Offhand;
 public void OnSelect(BaseEventData e){View.Select(ItemId);}
 public void OnSubmit(BaseEventData e){if(!string.IsNullOrEmpty(ItemId)){View.Select(ItemId);View.ActSelected();}}
 public void OnPointerClick(PointerEventData e){if(e.button==PointerEventData.InputButton.Right&&!string.IsNullOrEmpty(ItemId)){View.Select(ItemId);View.ActSelected();}}
 public void OnBeginDrag(PointerEventData e){if(e.button!=PointerEventData.InputButton.Left||EquipmentTarget||string.IsNullOrEmpty(ItemId))return;RiftInventoryPaperdoll.CancelDrag();RiftInventoryPaperdoll.DragView=View;RiftInventoryPaperdoll.DragItem=ItemId;RiftInventoryPaperdoll.DragOwner=gameObject;RiftInventoryPaperdoll.DragLabel=RiftWidgets.Label(GetComponentInParent<Canvas>().transform,View.Item(ItemId).Name,0,0,300,36,20,new Color(1,.85f,.5f));OnDrag(e);e.eligibleForClick=false;}
 public void OnDrag(PointerEventData e){e.eligibleForClick=false;if(RiftInventoryPaperdoll.DragLabel)RiftInventoryPaperdoll.DragLabel.rectTransform.position=e.position+new Vector2(18,-18);}
 public void OnDrop(PointerEventData e){if(RiftInventoryPaperdoll.DragView!=View||e.pointerDrag!=RiftInventoryPaperdoll.DragOwner)return;if(EquipmentTarget)View.Equip(RiftInventoryPaperdoll.DragItem,Offhand);else View.MoveItem(RiftInventoryPaperdoll.DragItem,Position);e.eligibleForClick=false;}
 public void OnEndDrag(PointerEventData e){e.eligibleForClick=false;RiftInventoryPaperdoll.CancelDrag();}
 public void OnDisable(){if(RiftInventoryPaperdoll.DragOwner==gameObject)RiftInventoryPaperdoll.CancelDrag();}
}
